import {
  integer,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { encryptedJson } from "@/shared/server/crypto";
// AD-9: another slice's schema file reaches `students(id)` only through the
// read-only `studentIdRef`.
import { studentIdRef } from "../../identity/server/schema";

// One row per Application (AD-8, AD-10), owned by `application`. The id is
// generated by the client and reused until the inputs change. Everything
// personal is an encrypted column (AD-11): `job` is `{jobAd, jobTitle,
// employer}`, `analysis` the phase-1 result, `gaps`, `letter` and
// `letter_check` the phase-2 parts (null until written). The CV text is never
// stored here. Plain only: ids, the fingerprint, `seq`, `match_score`, the revs
// and the timestamps.
export const applications = pgTable(
  "applications",
  {
    id: uuid("id").primaryKey(),
    studentId: uuid("student_id")
      .notNull()
      .references(studentIdRef, { onDelete: "cascade" }),
    job: encryptedJson("job").notNull(),
    analysis: encryptedJson("analysis").notNull(),
    gaps: encryptedJson("gaps"),
    letter: encryptedJson("letter"),
    letterCheck: encryptedJson("letter_check"),
    fingerprint: text("fingerprint").notNull(),
    seq: integer("seq").notNull(),
    matchScore: integer("match_score").notNull(),
    letterRev: integer("letter_rev").notNull().default(0),
    gapsRev: integer("gaps_rev").notNull().default(0),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    unique("applications_student_id_seq_unique").on(table.studentId, table.seq),
  ],
);
